{
  "artifact": "LinkedIn Outreach Orchestrator (LIC)",
  "version": "LIC_10-03-2025_v7.5",
  "metadata": {
    "name": "LinkedIn Intelligent Composer (LIC)",
    "version": "LIC_10-03-2025_v7.13.2",
    "last_updated": "10-03-2025",
    "description": "Orchestration system for LinkedIn outreach with unified RAG, claim verification, job application linkage, Unicode filtering, enhanced reasoning toggles",
