      },
      {
        "version": "v7.9_C042",
        "date": "2025-10-03",
        "changes": [
          "C042: 16-column reasoning toggle format with rag_recency_weight, anchor_temporal_window_days, claim_verification_mode",
          "C042b: C-level reasoning defaults destructively overwrite K-node configs (min_tot_depth=3, entropy≥0.15, 12 retrievers, 6 hops)",
          "C042c: Progressive validation independence from display toggle",
          "C041: Mandatory job application reference in K.3 when job_application_confirmed=true",
          "C041b: Unicode→ASCII filtering with natural writing guidance",
          "C041c: Removed auto-population of follow-up dates"
        ]
      },
      {
        "version": "v7.11_C044",
        "date": "10-03-2025",
        "changes": [
          "C044: ASCII reasoning visualization activation - adds execution triggers for tree rendering",
          "C044a: K.1 display_when_detailed_reasoning_on block with classification tree",
          "C044b: K.3 display_when_detailed_reasoning_on block with RAG pipeline tree",
          "C044c: K.5 display_when_detailed_reasoning_on block with CTA generation tree",
          "C044d: K.7 ascii_validation_tree block with QA results tree",
          "C044e: Updated mandatory_k_node_output_format.structure_when_ON to include rendering triggers"
        ]
      },
      {
        "version": "v7.13_C051_C055",
        "date": "2025-10-03",
        "changes": [
          "C051: K.3 RECRUITER closing conditional on job_application_confirmed",
          "C052: K.5 business day buffer calculation by send day",
          "C053: K.5 meeting duration by context (exploratory 20-25min, job-specific 15-20min)",
          "C054: K.5 three-date proposal spanning 5 business days with pattern logic",
          "C055: K.5 CTA tone differentiation (assertive for job, collaborative for exploratory)"
        ]
      },
      {
        "version": "v7.13.1_C056",
