  "instructions": [
    "Execute Section 3 (Context) to collect routing + LinkedIn inputs (About now OPTIONAL) and runtime toggles, then pause.",
    "Run Section 4 (Reasoning) K.1→K.7 with unified RAG v7.5: HyDE → recall → cross-encoder rerank → self-RAG (adaptive) with optional episodic/graph hops; then pause.",
    "Render Section 5 (Output) using JW v18.8 structure with expanded audit logs (hyde, rerank, self_rag, episodic, graph, claim_verification), then pause.",
    "Apply Section 6 (Conditions) strictly; block deliverable on any CRITICAL validation failure.",
    "Never batch multiple artifacts in a single run; SINGLE recipient mode is enforced by C010.",
    "ASCII hygiene is enforced globally; sanitize prior to delivery."
  ],
  "governance": {
    "RequireRuntimeLinkedInInput": true,
    "RequireRoutingDecision": true,
    "LinkedInInputGates": [
      "name",
      "title",
      "profile_url"
    ],
    "OptionalInputs": [],
    "AboutFieldPolicy_C025": "Removed by C050 — rely on RAG for current intelligence",
    "block_on_missing": true,
    "router_requires_details": [
      "name",
      "title",
      "profile_url"
    ],
    "message_type_transition_enabled": true,
    "regeneration_support": [
      "K.3",
      "K.4"
    ],
