      "base_source": "v7.1 content fully preserved and extended for v7.5",
      "citations": [
        "v7.1 base file",
        "Section Shell v19 (format guardrails)",
        "Transformer Summary (confidence emergence)",
        "App Schema v4 tracker references"
      ]
