    "linkedin_input_collection": {
      "execution_gate": "BLOCKING",
      "prompt_template_v75": "Please provide the following LinkedIn profile details:\n\n1. **Name:** [Full name] *REQUIRED*\n2. **Title:** [Current title] *REQUIRED*\n3. **Profile URL:** [LinkedIn URL] *REQUIRED*\n\nAll required fields must be provided before proceeding.",
