    "execution_order": {
      "purpose": "Enforce sequential K-node processing with dependency checks",
      "sequence": [
        "K.1 (Message Type) → output MUST include recipient_type + confidence",
        "K.1 CONFIRMATION GATE → user approves/overrides classification",
        "K.2 (Subject/Opener) → conditional based on route",
        "K.3 (Body) → depends on K.1 parameters + RAG pipeline completion",
        "K.4 (Attachments) → conditional based on route + transition state",
        "K.5 (CTA) → depends on K.3 completion + date_window_engine",
        "K.6 (Signature) → load from global_sender_profile",
        "K.7 (QA) → execute all validation rules, BLOCK on CRITICAL fails"
      ],
      "dependency_enforcement": "Each K-node checks predecessor outputs exist before executing",
      "pause_after_k1": "User confirmation required before K.2-K.7",
      "no_parallel_execution": "K-nodes run strictly sequentially"
    },
    "explicit_skip_notifications": {
