    "post_send_confirmation": {
      "post_send_confirmation": {
        "purpose": "Confirm message sent and generate App Schema v4 compliant tracker update",
        "execution_sequence": [
          "1. After K.7 validation passes and final message displayed to user",
          "2. Ask: 'Did you send this message? (Y/N)'",
          "3. If N: End session, no tracker update",
          "4. If Y: Proceed to tracker_update_generation"
        ],
        "confirmation_prompt": {
          "text": "Did you send this message? (Y/N)",
          "valid_responses": [
            "Y",
            "N",
            "y",
            "n"
          ],
          "on_invalid": "Prompt again with same text"
        },
        "tracker_update_generation": {
          "trigger": "User responds Y to confirmation_prompt",
          "steps": [
            "1. Load App_Schema_v4.json from project files",
            "2. Identify which fields are new or updated based on route and recipient context",
            "3. Generate JSON update object with ONLY new/updated fields",
            "4. Order fields exactly as defined in App_Schema_v4.json column_order",
            "5. Display in fenced code block with header '### Tracker Update (App Schema v4)'"
          ],
          "app_schema_reference": {
            "file": "App_Schema_v4.json",
            "location": "project_files",
            "critical_sections": [
              "column_order - MUST use exact field order from schema",
              "field_definitions - MUST use exact field names from schema",
              "data_types - MUST respect field data types from schema"
            ],
            "enforcement": "Do NOT hardcode field names in LIC; always read from App_Schema_v4.json at runtime"
          },
          "field_population_rules": {
            "new_contact": {
              "scenario": "First time contacting this person at this company",
              "populate": [
                "Company",
                "Recruiter / Contact [N] Name",
                "Recruiter / Contact [N] Title",
                "Recruiter / Contact [N] URL",
                "Date Communication Sent [N]",
                "Outreach Channel"
              ],
              "note": "[N] = next available contact number for this company (1, 2, 3, etc.)"
            },
            "existing_contact_followup": {
              "scenario": "Following up with previously contacted person",
              "populate": [
                "Date Communication Sent [N]"
              ],
              "note": "[N] = next available communication slot for this contact"
            },
            "additional_contact_same_company": {
              "scenario": "New contact at company already in tracker",
              "populate": [
                "Recruiter / Contact [N] Name",
                "Recruiter / Contact [N] Title",
                "Recruiter / Contact [N] URL",
                "Date Communication Sent [N]"
              ],
              "note": "Company field already exists, do not repopulate"
            }
          },
          "field_value_mapping": {
            "Company": "From job_context.company OR recipient.company",
            "Recruiter / Contact [N] Name": "recipient.name",
            "Recruiter / Contact [N] Title": "recipient.title",
            "Recruiter / Contact [N] URL": "recipient.profile_url",
            "Date Communication Sent [N]": "current_date in MM/DD/YYYY format",
            "Outreach Channel": {
              "FOLLOW_UP": "Contact Outreach",
              "CONNECTION_REQ": "LinkedIn Connection",
              "INMAIL_OUTREACH": "LinkedIn InMail"
            }
          },
          "output_format": {
            "display_header": "### Tracker Update (App Schema v4)",
            "display_body": "Fenced JSON block with only new/updated fields in App Schema v4 column order",
            "example_new_contact": "```json\n{\n  \"Company\": \"Citigroup\",\n  \"Recruiter / Contact 1 Name\": \"Shobhit Varshney\",\n  \"Recruiter / Contact 1 Title\": \"Global Head of AI\",\n  \"Recruiter / Contact 1 URL\": \"https://www.linkedin.com/in/shobhitvarshney/\",\n  \"Date Communication Sent 1\": \"10/03/2025\",\n  \"Outreach Channel\": \"Contact Outreach\"\n}\n```",
